-- Auto-generated Apple catalog for Stive Landry Store
-- Generated by scripts/generate-apple-catalog.mjs — do not edit by hand.
-- Run AFTER 001_initial.sql, 002_sellers.sql, 003_category_images.sql, 004_payment_methods.sql
-- Safe to re-run: upserts by product slug / variant sku.

-- Clear truncated SKUs from a previous failed seed (e.g. APP-MACBOOKAIRM2 collisions).
-- Only removes catalog rows whose sku starts with APP- and is shorter than 20 chars (old generator).
delete from public.product_variants
where product_id in (
  select id from public.products
  where sku like 'APP-%' and length(replace(sku, 'APP-', '')) <= 12
);
delete from public.products
where sku like 'APP-%' and length(replace(sku, 'APP-', '')) <= 12;

insert into public.categories (name, slug, description, image_url, sort_order, show_on_home)
values
  ('Laptop / MacBook', 'laptop-macbook', 'MacBook Air, MacBook Pro and premium laptops.', '/categories/macbook.jpg', 10, true),
  ('iPhone', 'iphone', 'iPhone from 7 to the latest generation.', '/categories/iphone.jpg', 20, true),
  ('iPad', 'ipad', 'iPad, iPad Air, iPad mini and iPad Pro.', '/categories/iphone.jpg', 25, true),
  ('Mac desktop', 'mac-desktop', 'iMac, Mac mini, Mac Studio and Mac Pro.', '/categories/macbook.jpg', 15, true),
  ('Accessories', 'accessories', 'Cases, chargers, cables, Pencil, keyboards.', '/categories/accessories.jpg', 40, true),
  ('Audio', 'audio', 'AirPods, HomePod and headphones.', '/categories/audio.jpg', 30, true),
  ('Wearables', 'wearables', 'Apple Watch Series, SE and Ultra.', '/categories/wearables.jpg', 50, true)
on conflict (slug) do update set
  description = excluded.description,
  sort_order = excluded.sort_order,
  show_on_home = true;

insert into public.brands (name, slug) values ('Apple', 'apple'), ('Anker', 'anker')
on conflict (slug) do nothing;

insert into public.products (sku, name, slug, brand_id, category_id, description, specs, base_price, featured, status)
select
  'APP-IPHONE7',
  'iPhone 7',
  'iphone-7',
  b.id,
  c.id,
  'iPhone 7 — authentic Apple product at Stive Landry Store. Choose storage and colour; live stock and pre-order available.',
  '{}'::jsonb,
  65000,
  false,
  'active'
from public.brands b, public.categories c
where b.slug = 'apple' and c.slug = 'iphone'
on conflict (slug) do update set
  sku = excluded.sku,
  name = excluded.name,
  description = excluded.description,
  base_price = excluded.base_price,
  featured = excluded.featured,
  status = 'active',
  brand_id = excluded.brand_id,
  category_id = excluded.category_id;

insert into public.product_variants (product_id, model, storage, color, sku, price, image_urls, reservable, preorder_enabled, status)
select p.id, 'iPhone 7', '32 Go', 'Noir', 'APP-IPHONE7-32GO-NOIR', 65000,
  array['/products/iphone-7.png?v=cutout'],
  true, true, 'active'
from public.products p where p.slug = 'iphone-7'
on conflict (sku) do update set
  model = excluded.model,
  storage = excluded.storage,
  color = excluded.color,
  price = excluded.price,
  image_urls = excluded.image_urls,
  reservable = true,
  preorder_enabled = true,
  status = 'active';

update public.inventory i
set total_stock = greatest(i.total_stock, 1), min_stock = 1
from public.product_variants v
where v.sku = 'APP-IPHONE7-32GO-NOIR' and i.variant_id = v.id;

