select
  'APP-IMAC24M3',
  'iMac 24 inch M3',
  'imac-24-m3',
  b.id,
  c.id,
  'iMac 24 inch M3 — authentic Apple product at Stive Landry Store. Choose storage and colour; live stock and pre-order available.',
  '{}'::jsonb,
  920000,
  true,
  'active'
