insert into public.products (sku, name, slug, brand_id, category_id, description, specs, base_price, featured, status)
select
  'APP-IMAC24M4',
  'iMac 24 inch M4',
  'imac-24-m4',
  b.id,
  c.id,
  'iMac 24 inch M4 — authentic Apple product at Stive Landry Store. Choose storage and colour; live stock and pre-order available.',
  '{}'::jsonb,
  1080000,
  false,
  'active'
from public.brands b, public.categories c
where b.slug = 'apple' and c.slug = 'mac-desktop'
on conflict (slug) do update set
  sku = excluded.sku,
  name = excluded.name,
  description = excluded.description,
  base_price = excluded.base_price,
  featured = excluded.featured,
  status = 'active',
  brand_id = excluded.brand_id,
  category_id = excluded.category_id;

